from pydantic import BaseModel, ConfigDict, ValidationError
from typing import Literal

class Action(BaseModel):
    model_config = ConfigDict(extra="forbid")   # reject injected keys
    tool: Literal["search", "get_order"]
    query: str

def parse_action(raw: str) -> Action:
    try:
        return Action.model_validate_json(raw)
    except ValidationError as e:
        raise ValueError(f"rejected malformed action: {e}") from e

ALLOWED_TOOLS = {"search", "get_order"}
ALLOWED_DOMAINS = {"docs.example.com", "api.example.com"}

def check_action(tool: str, args: dict) -> None:
    if tool not in ALLOWED_TOOLS:          # allow-list, not deny-list
        raise ValueError(f"tool not allowed: {tool}")
    if tool == "search" and len(args.get("query", "")) > 200:
        raise ValueError("query too long")
    url = args.get("url")
    if url and url.split("/")[2] not in ALLOWED_DOMAINS:
        raise ValueError("domain not allow-listed")
# a validated action can still be dangerous; argument checks catch that

import logging
log = logging.getLogger("agent.safety")

def safe_act(raw: str, run_tool):
    try:
        action = parse_action(raw)           # schema check
        check_action(action.tool, {"query": action.query})  # allow-list
    except ValueError as e:
        log.warning("blocked action: %s", e)  # observable
        return "action blocked by validation"  # fail CLOSED
    return run_tool(action.tool, {"query": action.query})

