from urllib.parse import urlparse
from pydantic import BaseModel, ConfigDict, ValidationError

ALLOWED_HOSTS = {"docs.example.com", "api.example.com"}

class ToolCall(BaseModel):
    model_config = ConfigDict(extra="forbid")
    tool: str
    url: str

def validate_tool_call(raw_json: str) -> ToolCall:
    try:
        # parse + type-check; extra=forbid rejects injected keys
        call = ToolCall.model_validate_json(raw_json)
    except ValidationError as e:
        raise ValueError(f"rejected malformed tool call: {e}") from e
    except Exception as e:
        raise ValueError(f"could not parse tool call JSON: {e}") from e
    # allow-list the tool (fail safe against anything unexpected)
    if call.tool != "fetch":
        raise ValueError(f"tool not allowed: {call.tool}")
    # allow-list the URL host
    host = urlparse(call.url).hostname
    if host not in ALLOWED_HOSTS:
        raise ValueError(f"host not allow-listed: {host}")
    return call

from pydantic import BaseModel, ConfigDict, ValidationError
from typing import Callable

class Action(BaseModel):
    model_config = ConfigDict(extra="forbid")   # reject injected keys
    tool: str
    query: str

ALLOWED_TOOLS = {"search", "get_order"}
MAX_QUERY = 200

def dispatch(raw: str, run_tool: Callable[[str, str], str]) -> str:
    try:
        action = Action.model_validate_json(raw)     # parse + type check
        if action.tool not in ALLOWED_TOOLS:         # allow-list
            raise ValueError(f"tool not allowed: {action.tool}")
        if len(action.query) > MAX_QUERY:            # constrain argument
            raise ValueError("query too long")
    except (ValidationError, ValueError) as e:
        return f"blocked: {str(e).splitlines()[0]}"  # fail closed, no raise
    return run_tool(action.tool, action.query)

if __name__ == "__main__":
    def run_tool(tool, query):
        return f"ran {tool}({query!r})"
    print(dispatch('{"tool": "search", "query": "q3"}', run_tool))
    print(dispatch('{"tool": "wipe", "query": "x"}', run_tool))
